            Tags = """["sequences","walkthrough","admin"]""",
            ContentJson = """{"appRoute":"/sequences/new","startButtonLabel":"Tour the Definition Editor","steps":[{"element":"[data-testid='sequence-editor']","popover":{"title":"The Definition Editor","description":"Everything about one definition lives on this page: its name, its steps, the order they run in, and the gates that hold them.","side":"top"}},{"element":"[data-testid='sequence-editor-code']","popover":{"title":"Code","description":"A short, stable identifier such as FAI-ROUTING. Versions of the same definition share a code, so pick one you will not want to rename.","side":"bottom"}},{"element":"[data-testid='sequence-editor-name']","popover":{"title":"Name","description":"The name people see on the Definitions and Instances pages and on a job's Gates section.","side":"bottom"}},{"element":"[data-testid='sequence-editor-add-step']","popover":{"title":"Add Steps","description":"One row per step. Give each a short key and a name, set its Order, and optionally a Max dwell with what should happen when that time runs out.","side":"left"}},{"element":"[data-testid='sequence-editor-add-edge']","popover":{"title":"Add Edges","description":"An edge says the From step must finish before the To step can start. A step with no incoming edge is a start step. Mark an edge Rework only when it deliberately loops back.","side":"left"}},{"element":"[data-testid='sequence-editor-add-gate']","popover":{"title":"Add Gates","description":"Attach a condition to a step. Choose the Source (manual clearance, approval, time window, resource clock, or custom) and fill in the Config using the example shown under the row.","side":"left"}},{"element":"[data-testid='sequence-editor-save']","popover":{"title":"Save","description":"Saves the definition as a Draft. Forge checks the graph on save: duplicate keys, edges to unknown steps, and loops that are not marked Rework are rejected. Publish from the Definitions page when it is ready.","side":"bottom"}}]}"""
