            ContentType = TrainingContentType.QuickRef,
            EstimatedMinutes = 4,
            IsPublished = true,
            SortOrder = 4,
            AppRoutes = """["/sequences","/sequences/new","/sequences/instances"]""",
            Tags = """["sequences","reference"]""",
            ContentJson = """{"title":"Sequences Field Reference","groups":[{"heading":"Definition Header","items":[{"label":"Code","value":"Short stable identifier shared by every version of the definition (for example FAI-ROUTING)."},{"label":"Name","value":"Display name shown on the Definitions and Instances pages."},{"label":"Subject type","value":"Optional. The kind of record a run is for, such as Job. Needed for Auto-start and for gates that read from the subject."},{"label":"Auto-start on subject create","value":"Yes starts a run automatically for every new record of the subject type once the definition is published."},{"label":"Description","value":"Free text shown under the name on the Definitions page."}]},{"heading":"Step Fields","items":[{"label":"Key","value":"Short identifier used by edges and gates to refer to the step. Must be unique within the definition."},{"label":"Name","value":"What the step is called in a run."},{"label":"Order","value":"Display order in the list. It does not decide what runs first; edges do."},{"label":"Join","value":"All: every earlier step must be done before this one is Ready. Any: one is enough."},{"label":"Max dwell (min)","value":"Optional. How long the step may sit In progress before the dwell action fires."},{"label":"On dwell expiry","value":"Block holds the run, Flag marks it for attention, Escalate notifies the Escalate role."},{"label":"Escalate role","value":"The role notified when the dwell action is Escalate."}]},{"heading":"Edge Fields","items":[{"label":"From / To","value":"The From step must be Complete or Skipped before the To step can become Ready."},{"label":"Rework?","value":"Yes marks a deliberate loop back to an earlier step. Loops that are not marked Rework are rejected on save."}]},{"heading":"Gate Sources and Config","items":[{"label":"ManualClearance","value":"Go when someone presses Clear on the gate. Config may name a requiredRole that is allowed to clear it."},{"label":"Approval","value":"Go when an approved approval request exists for the record. Config: fromSubject true, or an explicit entityType and entityId."},{"label":"TimeWindow","value":"Go only between notBefore and notAfter dates in the config."},{"label":"ResourceClock","value":"Go while the named resource's clock has not expired. Config: resourceType and resourceId, or fromSubject true."},{"label":"Custom","value":"Go according to a condition your Forge has been set up with; config names it by key. An unknown key reads No-Go."},{"label":"On expiry","value":"What a time-based gate does when its window or clock runs out: Block, Flag, or Escalate."}]},{"heading":"Statuses","items":[{"label":"Definition: Draft","value":"Editable. Cannot be used to start a run."},{"label":"Definition: Published","value":"Frozen. Runs can start. Use New version to change it."},{"label":"Definition: Retired","value":"No new runs. Runs in progress keep going."},{"label":"Run: Running / Completed / Cancelled","value":"A run completes on its own when every step is Complete or Skipped."},{"label":"Step: Pending","value":"Waiting on earlier steps or a gate."},{"label":"Step: Ready","value":"Earlier steps are done and every gate is Go. Press Start."},{"label":"Step: In progress","value":"Started. Press Complete when the work is done."},{"label":"Step: Complete / Skipped","value":"Both count as done for the steps after it. Rework resets from here."},{"label":"Blocked","value":"Shown on a step whose earlier steps are done but a gate is No-Go. The reason is listed under the step."},{"label":"Gate: Unknown / Go / NoGo","value":"Unknown means not evaluated yet. Only Go lets the step through."}]},{"heading":"Actions That Require a Reason","items":[{"label":"Override","value":"Forces a gate to Go permanently for this run."},{"label":"Skip","value":"Marks a step done without doing it."},{"label":"Rework","value":"Resets a step and everything after it to Pending."},{"label":"Cancel run","value":"Ends the run permanently."}]}]}"""
        });

