            AppRoutes = """["/sequences"]""",
            Tags = """["sequences","quiz"]""",
            ContentJson = """{"passingScore": 80, "shuffleQuestions": false, "shuffleOptions": true, "showExplanationsAfterSubmit": true, "questions": [{"id": "q1", "text": "A step's earlier steps are all complete, but it shows as Blocked. What does that mean?", "options": [{"id": "q1a", "text": "Someone set the step to Blocked by hand", "isCorrect": false}, {"id": "q1b", "text": "At least one gate on the step is not reading Go", "isCorrect": true}, {"id": "q1c", "text": "The step's Max dwell has run out", "isCorrect": false}, {"id": "q1d", "text": "The definition was retired", "isCorrect": false}], "explanation": "Blocked is never set by a person. It is what a step looks like when its predecessors are done but a gate is still No-Go; the reason is shown under the step."}, {"id": "q2", "text": "You need to change a step on a definition that is already Published. What do you do?", "options": [{"id": "q2a", "text": "Open it and edit it; changes apply to runs in progress", "isCorrect": false}, {"id": "q2b", "text": "Retire it and create a brand-new definition with a different code", "isCorrect": false}, {"id": "q2c", "text": "Press New version, edit the new draft, then publish it", "isCorrect": true}, {"id": "q2d", "text": "Cancel every run, then edit the definition", "isCorrect": false}], "explanation": "Published definitions are frozen. New version copies it into a fresh draft; runs already going keep the version they started on."}, {"id": "q3", "text": "A gate's source is Manual clearance. How does it become Go?", "options": [{"id": "q3a", "text": "It turns Go automatically after the step before it completes", "isCorrect": false}, {"id": "q3b", "text": "Someone with the right role presses Clear on the gate", "isCorrect": true}, {"id": "q3c", "text": "The subject record gets an approved approval request", "isCorrect": false}, {"id": "q3d", "text": "The Max dwell timer expires", "isCorrect": false}], "explanation": "Manual clearance means a person's Clear press is the sign-off. Approval-source gates are the ones that read approval requests."}, {"id": "q4", "text": "Which of these actions does NOT ask for a reason?", "options": [{"id": "q4a", "text": "Override", "isCorrect": false}, {"id": "q4b", "text": "Rework", "isCorrect": false}, {"id": "q4c", "text": "Re-evaluate", "isCorrect": true}, {"id": "q4d", "text": "Cancel run", "isCorrect": false}], "explanation": "Re-evaluate just asks Forge to look at every gate again; it changes nothing on its own. Override, Skip, Rework, and Cancel all record a required reason."}, {"id": "q5", "text": "A gate is set to a Custom source, but the key in its config is not one your Forge knows. What happens?", "options": [{"id": "q5a", "text": "The gate reads Go so the run is not held up", "isCorrect": false}, {"id": "q5b", "text": "The gate reads No-Go and the step stays blocked", "isCorrect": true}, {"id": "q5c", "text": "The definition cannot be saved", "isCorrect": false}, {"id": "q5d", "text": "The step is skipped automatically", "isCorrect": false}], "explanation": "Sequences fail closed. A condition Forge cannot answer reads No-Go, with a reason on the gate, until it is fixed or overridden."}]}"""
